(() => {
  const style=document.createElement('style');style.textContent=`.course{max-width:960px;margin:auto}.course-hero{padding:30px;border-radius:24px;background:var(--navy);color:#fff;box-shadow:var(--shadow)}.course-hero h2{margin:8px 0;font-size:clamp(1.55rem,3vw,2.3rem)}.course-hero p{color:#dce8f5;line-height:1.7}.course-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:18px 0}.course-day{padding:14px;border:1px solid var(--line);border-radius:15px;background:#fff}.course-day b{display:block;color:var(--navy)}.course-day small{color:var(--muted)}.course-day.active{border-color:var(--blue);background:#f4f9ff}.course-day.done{background:var(--mint);border-color:#9fd4bd}.lesson{background:#fff;padding:28px;border-radius:24px;box-shadow:var(--shadow)}.lesson h2,.lesson h3{color:var(--navy)}.lesson h3{font-size:1.06rem;margin:0}.lesson-step{margin:19px 0;padding:18px;border:1px solid var(--line);border-radius:16px}.step-head{display:flex;align-items:center;justify-content:space-between;gap:8px}.step-time{color:var(--muted);font-size:.88rem}.word-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.word-card{padding:12px;border:1px solid #d7e5f4;border-radius:12px;background:#f8fbff}.word-card b{color:var(--navy);font-size:1.05rem}.word-card p{margin:6px 0;line-height:1.55}.word-card small{display:block;color:var(--muted);line-height:1.5}.word-actions{display:flex;gap:7px;margin-top:9px}.word-actions button{font:inherit;font-size:.78rem;padding:5px 8px;border-radius:7px;border:1px solid var(--line);background:#fff;color:var(--navy);cursor:pointer}.word-actions button.selected{background:var(--mint);border-color:#86c9ad}.collocation{padding:9px 0;border-top:1px solid var(--line);line-height:1.6}.collocation:first-of-type{border-top:0}.collocation b{color:var(--navy)}.material{padding:15px;border-radius:12px;background:#f6faff;border:1px solid #d7e5f4;line-height:1.8}.question{margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}.question label{display:block;font-weight:600;line-height:1.55}.lesson input,.lesson textarea{box-sizing:border-box;width:100%;margin-top:8px;padding:11px 12px;border:1px solid var(--line);border-radius:10px;font:inherit}.lesson textarea{min-height:72px;resize:vertical}.answer,.feedback{display:none;margin-top:10px;padding:12px;border-radius:10px;line-height:1.65}.answer.show{display:block;background:#f6faff;color:#314963}.feedback.show{display:block}.feedback.good{background:var(--mint);color:#245846}.feedback.bad{background:#fff4f1;color:#8b3c35}.lesson-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.progress-strip{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.progress-chip{background:#eef5fb;border-radius:999px;padding:7px 10px;color:#38536e;font-size:.88rem}.course-note{color:var(--muted);line-height:1.6}@media(max-width:720px){.course-grid{grid-template-columns:1fr 1fr}.word-grid{grid-template-columns:1fr}.lesson{padding:20px}}`;document.head.appendChild(style);
  const K='ci-jing-week1-v3',load=()=>{try{return {...{day:0,done:[],status:{}},...JSON.parse(localStorage.getItem(K))}}catch{return{day:0,done:[],status:{}}}},save=s=>localStorage.setItem(K,JSON.stringify(s));
  const D=[
    {t:'证据与表达 · 起步',w:[['provide','提供','provide sb with sth','The school provides students with a quiet place to read.'],['reflect','反映','reflect students’ needs','The survey reflects what students need most.'],['evidence','证据','enough evidence','There is not enough evidence to support the claim.'],['support','支持','support a conclusion','The data cannot support that conclusion.'],['affect','影响','affect concentration','A lack of sleep may affect concentration.'],['acquire','获得','acquire skills','Students acquire skills through practice.']],c:[['provide sb with sth','向某人提供某物'],['support a conclusion','支持一个结论'],['be based on','以……为基础'],['have an effect on','对……有影响']],g:['evidence 是不可数名词：much / enough evidence。','被动语态：A guide is provided to students。'],p:'A school library began opening for one extra hour after classes. More students visited it, especially those preparing group projects. Some said the quieter space helped them concentrate. However, the school did not compare the exam results of users with those of non-users.',a:'材料中哪些是事实？为什么“开放时间提高成绩”还不能成立？',ex:'事实是更多学生使用图书馆。限制是学校没有比较使用者和未使用者的成绩，所以不能证明成绩提高。',q:[['The survey ___ students’ needs.','reflects'],['The club provides members ___ a guide.','with'],['There is enough ___ to support the claim.','evidence'],['The school did not ___ exam results.','compare']]},
    {t:'证据与表达 · 比较',w:[['compare','比较','compare A with B','The study compared users with non-users.'],['conclusion','结论','draw a conclusion','It is too early to draw a conclusion.'],['measure','衡量','measure results','The school did not measure results.'],['decline','下降','a decline in','There was a decline in visits.'],['available','可利用的','be available to','The report is available to students.'],['approach','方法','an approach to','This is an approach to reading.']],c:[['compare A with B','把 A 与 B 比较'],['draw a conclusion','得出结论'],['a decline in','在……方面的下降'],['be available to','可供……使用']],g:['compare 要交代对象：compare users with non-users。','not necessarily 表示“未必”，限制结论强度。'],p:'After a reading corner was added, visitor numbers increased. The school collected comments from visitors, but did not compare their reading scores with those of students who never used the corner.',a:'分别写一句：材料能得出什么结论？不能得出什么结论？',ex:'可以确定使用人数增加；不能证明阅读能力提高，因为没有比较两组的成绩。',q:[['Compare users ___ non-users.','with'],['It is too early to draw a ___.','conclusion'],['The change does not ___ improve achievement.','necessarily'],['There was a decline ___ visits.','in']]},
    {t:'让步与限定 · 语法语境',w:[['claim','主张','make a claim','The report makes a strong claim.'],['demonstrate','证明','demonstrate that','The figures do not demonstrate change.'],['respond','回应','respond to','Students responded to the survey.'],['maintain','保持','maintain a balance','Maintain a balance in study.'],['likely','可能的','be likely to','The change is likely to affect habits.'],['range','范围','a range of','The library offers a range of books.']],c:[['make a claim','提出主张'],['be likely to','可能会……'],['respond to','回应……'],['a range of','一系列……']],g:['Although 引导从句时，主句不再用 but。','被动表达：The claim is not supported by evidence。'],p:'Although more students used the library, the claim that their grades improved was not supported by enough evidence. The school collected visitor numbers but had not measured changes in grades.',a:'为什么 although 后不能接 but？定位“主张未被支持”的证据。',ex:'although 本身已经表示让步，不能再重复 but；学校没有测量成绩变化，是限制证据。',q:[['The claim was not ___ by evidence.','supported'],['The report makes a strong ___.','claim'],['Students responded ___ the survey.','to'],['Although it rained, ___ we went out. 应删去的词。','but']]},
    {t:'阅读推断 · 证据链',w:[['indicate','表明','indicate that','The figures indicate that visits increased.'],['factor','因素','a factor in','Practice is a factor in progress.'],['specific','具体的','specific information','Look for specific information.'],['vary','变化','vary from A to B','Results vary from student to student.'],['assume','假设','assume that','Do not assume two events connect.'],['benefit','受益','benefit from','Students may benefit from feedback.']],c:[['indicate that','表明……'],['a factor in','……的一个因素'],['vary from A to B','因 A 与 B 而不同'],['benefit from','从……中受益']],g:['evidence that + 从句；evidence of + 名词。','may 是可能，不表示已证实的事实。'],p:'A teacher asked students to write short reading notes for four weeks. Most students said the notes helped them notice linking words. Their weekly quizzes improved. Yet the class had no comparison group, and several students received extra tutoring.',a:'分别写：直接事实、合理推断、不能下的结论。',ex:'事实是学生说笔记有帮助、周测提高；可推断笔记可能有帮助；不能证明笔记单独导致提高，因为没有比较组且有额外辅导。',q:[['The figures ___ that visits increased.','indicate'],['Results vary ___ student to student.','from'],['Students may ___ from feedback.','benefit'],['Do not ___ two events are connected.','assume']]},
    {t:'周内迁移 · 综合验证',w:[['reliable','可靠的','reliable information','Use reliable information when judging.'],['require','要求','require sb to do sth','The task requires students to explain.'],['issue','问题','address an issue','The plan addresses an issue.'],['relevant','相关的','be relevant to','The detail is relevant to the question.'],['contribute','促成','contribute to','Practice contributes to progress.'],['identify','识别','identify the reason','Identify the reason for change.']],c:[['reliable information','可靠信息'],['be relevant to','与……相关'],['contribute to','促成……'],['identify the reason','找出原因']],g:['require sb to do：requires students to explain。','contribute to 中 to 是介词，后接名词或动名词。'],p:'A report found that fewer students chose printed books in one term. It did not ask students why. It also did not show whether total reading time changed or whether students used digital books instead.',a:'报告反映了什么？没有提供什么证据？',ex:'它反映选择纸质书的学生变少；没有提供变化原因、总阅读量或数字阅读情况的证据。',q:[['Use ___ information when judging.','reliable'],['The detail is relevant ___ the question.','to'],['Practice contributes to ___.','progress'],['The report did not ___ why students chose differently.','ask']]}
  ];
  const hub=document.getElementById('studyHub'),shell=document.getElementById('studyShell');
  function home(){let s=load(),n=Math.min(s.day,4);hub.classList.remove('hidden');shell.classList.add('hidden');hub.innerHTML=`<div class="course"><div class="course-hero"><div class="eyebrow">第 1 周课程包 · 每天最多 20 分钟</div><h2>${s.day>4?'第 1 周已完成':'第 '+(n+1)+' 天 · '+D[n].t}</h2><p>${s.day>4?'本周已积累 30 个词汇、20 个固定搭配、10 个语法语境点和 5 次篇章训练。':'每天固定完成：6 个词汇、4 个搭配、2 个语法语境点、1 段完整篇章和 4 题闭卷验证。'}</p><div class="lesson-actions"><button class="primary" id="start">${s.day>4?'回看第 1 天':'开始今天的 20 分钟学习'}</button></div></div><div class="course-grid">${D.map((d,i)=>`<div class="course-day ${s.done.includes(i)?'done':''} ${i===n&&s.day<5?'active':''}"><b>第 ${i+1} 天</b><small>6词 · 4搭配 · 1篇</small></div>`).join('')}</div><div class="progress-strip"><span class="progress-chip">${s.done.length*6} / 30 词汇</span><span class="progress-chip">${s.done.length*4} / 20 搭配</span><span class="progress-chip">${s.done.length} / 5 篇章</span></div><p class="course-note">词汇范围参照已接入的国家课程标准底表；释义、例句、搭配和练习均为编辑学习内容，不标为上海高考正式真题或上海专属词表。</p></div>`;document.getElementById('start').onclick=()=>lesson(s.day>4?0:n)}
  function lesson(i){let d=D[i],s=load();hub.classList.add('hidden');shell.classList.remove('hidden');shell.innerHTML=`<div class="course"><button class="secondary study-back" id="back">返回本周计划</button><div class="lesson"><span class="badge">第 ${i+1} 天 · 连续 20 分钟课程</span><h2>${d.t}</h2><div class="lesson-step"><div class="step-head"><h3>1. 词汇学习</h3><span class="step-time">6分钟 · 6词</span></div><p>每个词都有词义、搭配和例句。选择“太简单”会降低后续出现频率；选择“需要复习”会提高出现优先级。</p><div class="word-grid">${d.w.map((x,j)=>`<article class="word-card"><b>${x[0]}</b><p>${x[1]} · <strong>${x[2]}</strong></p><small>${x[3]}</small><div class="word-actions"><button data-k="${i}-${j}" data-v="easy" class="${s.status[i+'-'+j]==='easy'?'selected':''}">太简单</button><button data-k="${i}-${j}" data-v="review" class="${s.status[i+'-'+j]==='review'?'selected':''}">需要复习</button></div></article>`).join('')}</div></div><div class="lesson-step"><div class="step-head"><h3>2. 固定搭配</h3><span class="step-time">3分钟 · 4组</span></div>${d.c.map((x,j)=>`<div class="collocation"><b>${j+1}. ${x[0]}</b> · ${x[1]}</div>`).join('')}</div><div class="lesson-step"><div class="step-head"><h3>3. 语法语境</h3><span class="step-time">3分钟 · 2点</span></div><p><b>1.</b> ${d.g[0]}</p><p><b>2.</b> ${d.g[1]}</p></div><div class="lesson-step"><div class="step-head"><h3>4. 篇章应用</h3><span class="step-time">5分钟 · 完整材料</span></div><div class="material">${d.p}</div><div class="question"><label>${d.a}</label><textarea placeholder="先写下判断；这一步是思考，不自动计分。"></textarea><button class="secondary" id="explain">查看参考解释</button><div class="answer" id="answer"><b>参考解释：</b>${d.ex}</div></div></div><div class="lesson-step"><div class="step-head"><h3>5. 闭卷验证</h3><span class="step-time">3分钟 · 4题</span></div><p>只测试本节已学内容。提交后统一批改；空答案不会计分。</p>${d.q.map((x,j)=>`<div class="question"><label>${j+1}. ${x[0]}</label><input data-a="${x[1]}" placeholder="写出英文答案"></div>`).join('')}<div class="lesson-actions"><button class="primary" id="grade">提交并批改</button></div><div class="feedback" id="feedback"></div></div></div></div>`;document.getElementById('back').onclick=home;document.getElementById('explain').onclick=()=>document.getElementById('answer').classList.add('show');shell.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>{let z=load();z.status[b.dataset.k]=b.dataset.v;save(z);shell.querySelectorAll('[data-k="'+b.dataset.k+'"]').forEach(x=>x.classList.toggle('selected',x.dataset.v===b.dataset.v))});document.getElementById('grade').onclick=()=>grade(i)}
  function grade(i){let f=[...shell.querySelectorAll('[data-a]')],right=0,rows=f.map((x,j)=>{let ok=x.value.trim()&&x.value.trim().toLowerCase().includes(x.dataset.a.toLowerCase());if(ok)right++;return (j+1)+'. '+(ok?'正确':'待巩固')+'：'+x.dataset.a});let box=document.getElementById('feedback');box.className='feedback show '+(right===4?'good':'bad');box.innerHTML='<b>'+right+' / 4 项正确</b><br>'+rows.join('<br>')+'<br><br>'+(right===4?'验证通过，明天会回忆今天的重点。':'待巩固项会进入后续复习优先级。');let s=load();if(!s.done.includes(i))s.done.push(i);s.day=Math.max(s.day,i+1);save(s);let b=document.getElementById('grade');b.textContent='返回本周计划';b.onclick=home}
  home();
})();
